cd "$ARCHON_HORIZON_ROOT" && "$HORIZON_BIN" usage --json 2>/dev/null | python3 -c "
import json,sys
d=json.load(sys.stdin)
for k in ['paused','recent_failure_reasons']:
    print(k,'=',d.get(k))
s=d.get('session') or {}
print('session tokens out:', s.get('output_tokens') or s.get('tokens_out'))
b=d.get('budget') or {}
print('budget:', {k:b.get(k) for k in list(b)[:6]})
" 2>/dev/null || echo "(usage parse failed)"
